INSERT INTO parks (name, lat, lon, region) SELECT 'Zoosafari Fasanolandia', 40.8313, 17.3499, 'Italy' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Zoosafari Fasanolandia');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Bruco Miniottovolante', 'Zoosafari Fasanolandia', 'Steel', 'D.P.V. Rides', 'Wacky Worm', 12.2, 13.4, 393.7, 0, 40, 1995, '1995', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Bruco Miniottovolante' AND park = 'Zoosafari Fasanolandia');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Bruco Miniottovolante' AND c.park = 'Zoosafari Fasanolandia' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
